/* ===== RESET & BASE ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #080414;
  --bg-panel: #070912;
  --bg-card: linear-gradient(165deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.012));
  --text: #e8ecf8;
  --text-soft: #b8c0d8;
  --text-muted: #9aa3bd;
  --text-dim: #8b93b0;
  --text-faint: #6b7390;
  --pink: #ff8ad8;
  --purple: #a78bfa;
  --cyan: #8fd0ff;
  --magenta: #e06bff;
  --tag-text: #9fb0d0;
  --tag-bg: rgba(130, 170, 255, 0.08);
  --tag-border: rgba(130, 170, 255, 0.16);
  --hairline: rgba(130, 170, 255, 0.08);
  --font-head: 'Space Grotesk', sans-serif;
  --font-body: 'Manrope', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Courier New', monospace;
}

