/* ===== FONTER =====
   Ligger på eget domene, så besøkende ikke kontaktes av Google.
   Variable fonter: én fil per familie dekker hele vektområdet. Kilde og lisens: fonts/README.md. */
@font-face {
  font-family: 'Space Grotesk';
  font-style: normal;
  font-weight: 300 700;
  font-display: swap;
  src: url('../fonts/spacegrotesk/spacegrotesk-latin.woff2') format('woff2');
  unicode-range: $UR;
}
@font-face {
  font-family: 'Manrope';
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url('../fonts/manrope/manrope-latin.woff2') format('woff2');
  unicode-range: $UR;
}
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-weight: 400 800;
  font-display: swap;
  src: url('../fonts/jetbrainsmono/jetbrainsmono-latin.woff2') format('woff2');
  unicode-range: $UR;
}

EOF
cat $S/ff.css css/style.css > $S/new.css && mv $S/new.css css/style.css
for f in index.html dev.html musikk.html om-meg.html; do sed -i '' -E '/fonts\.(googleapis|gstatic)\.com/d' $f; done
grep -rn -E 'googleapis|gstatic' --include='*.html' --include='*.css' --include='*.js' . || echo "ingen Google-referanser"
