import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
const ext = [];
p.on('request', r => { if (!r.url().startsWith('http://localhost:8765')) ext.push(r.url()); });
const fonts = [];
p.on('response', r => { if (r.request().resourceType() === 'font') fonts.push(`${r.status()} ${r.url().replace('http://localhost:8765','')}`); });
for (const pg of ['index.html','dev.html','musikk.html','om-meg.html']) {
  await p.goto('http://localhost:8765/' + pg, { waitUntil: 'networkidle' });
  await p.evaluate(() => document.fonts.ready);
  const st = await p.evaluate(() => [...document.fonts].filter(f => f.status === 'loaded').map(f => f.family).join(', '));
  console.log(pg, '| lastet:', st);
  await p.screenshot({ path: `${pg}.png` });
}
console.log('fontforespørsler:', [...new Set(fonts)]);
console.log('eksterne forespørsler:', ext.length ? ext : 'ingen');
await b.close();
EOF
node t.mjs

